// Restricted payroll.
//
// Salary figures are NEVER bundled with the app (the deployed site is static and readable by anyone with the URL).
// An authorised HR user imports the wages-register file (generated by scripts/import-data.py) on their own device.
// It is encrypted with a passcode (PBKDF2-SHA256 → AES-GCM) before it is stored, and only decrypted in memory
// after the passcode is entered. The Sl No → employee-code mapping is stored inside the same encrypted blob.

const KEY = 'quickair-hr:payroll';
const ITER = 250000;
const enc = new TextEncoder();
const dec = new TextDecoder();

/* Statutory deductions (CAPL rule, applied to every register row on import and unlock):
 *   PT  — ₹200 when monthly CTC ≥ ₹25,000, otherwise ₹0
 *   EPF — fixed on a ₹25,000 wage base × 12 %   = ₹3,000, whatever the CTC
 *   ESI — fixed on a ₹21,000 wage base × 0.75 % = ₹157.50 → ₹158 (ESIC rounds up), whatever the CTC
 * Total deductions and net salary are recomputed from these. */
export const PT_THRESHOLD = 25000;
export const PT_AMOUNT = 200;
export const PF_WAGE_BASE = 25000;
export const PF_RATE = 0.12;
export const ESI_WAGE_BASE = 21000;
export const ESI_RATE = 0.0075;

const r2 = (n) => Math.round(n * 100) / 100;

export function applyStatutory(row) {
  const ctc = Number(row.ctc ?? row.gross ?? 0);
  const ded = { ...(row.ded || {}) };
  ded.pt = ctc >= PT_THRESHOLD ? PT_AMOUNT : 0;
  ded.epf = Math.round(PF_WAGE_BASE * PF_RATE);
  ded.esi = Math.ceil(ESI_WAGE_BASE * ESI_RATE);
  const totalDed = r2(Object.values(ded).reduce((a, v) => a + (Number(v) || 0), 0));
  const gross = row.gross ?? null;
  return { ...row, ded, pfWages: PF_WAGE_BASE, esiWages: ESI_WAGE_BASE, totalDed,
    net: gross === null ? row.net : r2(Number(gross) - totalDed) };
}
const normalise = (data) => ({ ...data, rows: data.rows.map(applyStatutory) });

let session = null; // { key, salt, data }  — only while unlocked
const listeners = new Set();
const emit = () => listeners.forEach((fn) => fn());
export const onPayrollChange = (fn) => listeners.add(fn);

const b64 = (buf) => {
  const u = new Uint8Array(buf);
  let s = '';
  for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode(...u.subarray(i, i + 0x8000));
  return btoa(s);
};
const unb64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

function stored() {
  try { const raw = localStorage.getItem(KEY); return raw ? JSON.parse(raw) : null; } catch { return null; }
}

async function deriveKey(pass, salt) {
  const base = await crypto.subtle.importKey('raw', enc.encode(pass), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name: 'PBKDF2', salt, iterations: ITER, hash: 'SHA-256' }, base,
    { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
}

async function persist() {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, session.key, enc.encode(JSON.stringify(session.data)));
  const blob = { v: 1, month: session.data.month, rows: session.data.rows.length, salt: b64(session.salt), iv: b64(iv), ct: b64(ct) };
  localStorage.setItem(KEY, JSON.stringify(blob));
}

export function payrollStatus() {
  if (session) return 'unlocked';
  return stored() ? 'locked' : 'none';
}
export const payrollMeta = () => { const s = stored(); return s ? { month: s.month, rows: s.rows } : null; };
export const payrollData = () => (session ? session.data : null);

/** Validate a wages-register file produced by scripts/import-data.py. Returns an error string or null. */
function validate(d) {
  if (!d || d.kind !== 'quickair-hr-payroll' || d.version !== 1) return 'This is not a Quickair HR payroll file.';
  if (!/^\d{4}-\d{2}$/.test(d.month || '')) return 'Payroll month is missing.';
  if (!Array.isArray(d.rows) || !d.rows.length) return 'The file has no wage rows.';
  const sl = d.rows.map((r) => r.slNo);
  if (new Set(sl).size !== sl.length) return 'Duplicate Sl No in the file — fix the register and re-import.';
  return null;
}

export async function importPayroll(file, pass, confirm) {
  if (!window.crypto?.subtle) throw new Error('Secure storage needs HTTPS (or localhost).');
  if (!pass || pass.length < 6) throw new Error('Choose a passcode of at least 6 characters.');
  if (pass !== confirm) throw new Error('The two passcodes don’t match.');
  let data;
  try { data = JSON.parse(await file.text()); } catch { throw new Error('Could not read that file — expected the payroll .json.'); }
  const err = validate(data);
  if (err) throw new Error(err);
  // Keep an existing mapping for the same month if HR re-imports a corrected file.
  const prev = session && session.data.month === data.month ? session.data.map : null;
  data.map = { ...(data.map || {}), ...(prev || {}) }; // { slNo: 'CAPL_xxxx' } — manual links win
  data = normalise(data);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  session = { key: await deriveKey(pass, salt), salt, data };
  await persist();
  emit();
}

export async function unlockPayroll(pass) {
  const s = stored();
  if (!s) throw new Error('No payroll on this device.');
  const salt = unb64(s.salt);
  const key = await deriveKey(pass || '', salt);
  let data;
  try {
    const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64(s.iv) }, key, unb64(s.ct));
    data = JSON.parse(dec.decode(pt));
  } catch { throw new Error('Wrong passcode.'); }
  data = normalise(data); // older stored files pick up the current PT / EPF / ESI rule
  session = { key, salt, data };
  emit();
}

export function lockPayroll() { session = null; emit(); }

export function removePayroll() {
  session = null;
  try { localStorage.removeItem(KEY); } catch { /* ignore */ }
  emit();
}

/** Link a register row (Sl No) to an employee code. One code ↔ one row. */
export async function mapRow(slNo, code) {
  if (!session) throw new Error('Unlock payroll first.');
  const map = { ...session.data.map };
  if (code) {
    const clash = Object.entries(map).find(([s, c]) => c === code && Number(s) !== Number(slNo));
    if (clash) throw new Error(`${code} is already linked to Sl No ${clash[0]}.`);
    map[slNo] = code;
  } else delete map[slNo];
  session.data.map = map;
  await persist();
  emit();
}

export const rowFor = (code) => {
  if (!session) return null;
  const sl = Object.entries(session.data.map).find(([, c]) => c === code)?.[0];
  return sl ? session.data.rows.find((r) => String(r.slNo) === String(sl)) : null;
};

/** Labels in register order. Earnings are shown as in the register; ESI, EPF and PT come from applyStatutory(). */
export const EARN_LABELS = [
  ['basicVda', 'Basic + VDA'], ['hra', 'HRA'], ['ca', 'Conveyance (CA)'], ['ma', 'Medical (MA)'], ['sa', 'Special allowance (SA)'],
  ['bonus', 'Bonus'], ['ot', 'Overtime'], ['attnBonus', 'Attendance bonus'], ['otherEarnings', 'Other earnings'],
  ['arrearsIncentive', 'Arrears / incentive'],
];
export const DED_LABELS = [
  ['esi', 'ESI'], ['epf', 'EPF'], ['pt', 'Professional tax'], ['alreadyPaid', 'Already paid'], ['attDed', 'Attendance deduction'],
  ['salAdv', 'Salary advance'], ['tds', 'TDS'],
];
